import { query } from '../db.js';

export class PaymentRepository {
  findByOrder(orderId) {
    return new Promise((resolve, reject) => {
      query('payments', (p) => p.order_id === orderId,
        (err, rows) => (err ? reject(err) : resolve(rows)));
    });
  }

  findUncaptured() {
    return new Promise((resolve, reject) => {
      query('payments', (p) => p.captured === false,
        (err, rows) => (err ? reject(err) : resolve(rows)));
    });
  }
}
EOF
cat > src/services/payment-service.js <<'EOF'
import { PaymentRepository } from '../repositories/payment-repository.js';

const payments = new PaymentRepository();

export function findPaymentsForOrder(orderId) {
  return payments.findByOrder(orderId);
}

export async function uncapturedTotalCents() {
  const rows = await payments.findUncaptured();
  return rows.reduce((sum, p) => sum + p.amount_cents, 0);
}
EOF
cat > tests/payment-service.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { findPaymentsForOrder, uncapturedTotalCents } from '../src/services/payment-service.js';

test('findPaymentsForOrder finds the payment for an order', async () => {
  const rows = await findPaymentsForOrder(10);
  assert.equal(rows.length, 1);
  assert.equal(rows[0].amount_cents, 4200);
});

test('uncapturedTotalCents sums uncaptured payments', async () => {
  const total = await uncapturedTotalCents();
  assert.equal(total, 9900);
});
EOF
